enum EConsoleParameterType {
    CONSOLE_PARAM_SLONG = 1,
    CONSOLE_PARAM_ULONG = 2,
    CONSOLE_PARAM_FLOAT = 3,
    CONSOLE_PARAM_BOOL = 4,
    CONSOLE_PARAM_STRING = 5
